/**
 * The authored city kit (public/models/city-kit.glb, generated by
 * scripts/assets/build_city_kit.py): garden districts, town centre, solar,
 * wind, park, road and sprawl parts sharing ONE texture atlas and material,
 * with ambient occlusion baked into the vertex colours.
 *
 * `kitPart(name)` returns a fresh wrapper Group around a clone of the named
 * node (geometry and material are shared). Callers position the wrapper, never
 * the clone: the clone keeps its node transform. Returns null when the kit is
 * not loaded, so every builder keeps its procedural fallback (also forced with
 * `?procedural-city` for A/B review).
 */
import {
  AssetManager,
  BufferAttribute,
  Group,
  type BufferGeometry,
  type Mesh,
  type MeshStandardMaterial,
  type Object3D,
} from '@iwsdk/core';
import { LEAF_CROWN, SOLAR_GLASS } from './shared-materials.js';

export const CITY_KIT_ASSET = 'city-kit';

let prepared: Object3D | null | undefined;
/** Geometries and materials owned by the loaded kit (shared by every clone). */
const shared = new WeakSet<object>();

/** True for kit-owned geometry / material, which callers must never dispose. */
export function isKitResource(r: object | null | undefined): boolean {
  return !!r && shared.has(r);
}

/** Quantized (KHR_mesh_quantization) attributes -> Float32 once, so merging stays exact. */
function dequantize(geo: BufferGeometry): void {
  for (const name of Object.keys(geo.attributes)) {
    const a = geo.attributes[name] as BufferAttribute;
    if (a.array instanceof Float32Array) continue;
    const out = new Float32Array(a.count * a.itemSize);
    for (let i = 0; i < a.count; i++) for (let k = 0; k < a.itemSize; k++) out[i * a.itemSize + k] = a.getComponent(i, k);
    geo.setAttribute(name, new BufferAttribute(out, a.itemSize));
  }
}

function kitScene(): Object3D | null {
  if (prepared !== undefined) return prepared;
  if (typeof location !== 'undefined' && location.search.includes('procedural-city')) return (prepared = null);
  let scene: Object3D | null = null;
  try {
    scene = AssetManager.getGLTF(CITY_KIT_ASSET)?.scene ?? null;
  } catch {
    scene = null;
  }
  if (!scene) return null; // not loaded (yet): retry next call
  let mat: MeshStandardMaterial | null = null;
  scene.traverse((o) => {
    const mesh = o as Mesh;
    if (!mesh.isMesh) return;
    dequantize(mesh.geometry);
    mat = mesh.material as MeshStandardMaterial;
    shared.add(mesh.geometry);
    shared.add(mat);
  });
  const m = mat as MeshStandardMaterial | null;
  if (m?.map) {
    m.map.anisotropy = 4;
    // Solar panels keep the shared glow material (time travel drives its
    // emissive) but show the atlas' photovoltaic cells and the baked AO.
    SOLAR_GLASS.map = m.map;
    SOLAR_GLASS.color.set('#ffffff');
    SOLAR_GLASS.vertexColors = true;
    SOLAR_GLASS.needsUpdate = true;
    // Park crowns likewise: atlas foliage x baked AO, tinted by LEAF_CROWN.color.
    LEAF_CROWN.map = m.map;
    LEAF_CROWN.vertexColors = true;
    LEAF_CROWN.needsUpdate = true;
  }
  return (prepared = scene);
}

export function hasKit(): boolean {
  return kitScene() !== null;
}

export function kitPart(name: string): Group | null {
  const src = kitScene()?.getObjectByName(name);
  if (!src) return null;
  const clone = src.clone();
  clone.traverse((o) => {
    if ((o as Mesh).isMesh) {
      o.castShadow = true;
      o.receiveShadow = true;
    }
  });
  const g = new Group();
  g.add(clone);
  return g;
}
